// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        Helper helper = new Helper(c);
        vm.prank(caller);
        address returnedOwner = helper.getOwner();
        assertTrue(returnedOwner == address(this));
    }
}

contract Helper {
    StaxLPStaking c;
    constructor(StaxLPStaking _c) { c = _c; }
    function getOwner() external view returns (address) {
        return c.owner();
    }
}
